MagickBooleanType SkipMipmapImages(Image *image, DDSInfo *dds_info, int pixel_size, ExceptionInfo *exception) {
  if (!image || !dds_info || !exception) {
    return MagickFalse;
  }

  if (!dds_info->has_mipmap || (image->storage_class != DirectClass)) {
    return MagickTrue;
  }

  for (size_t level = 1; level < dds_info->mipmap_levels; level++) {
    size_t width = image->columns >> level;
    size_t height = image->rows >> level;

    if (width == 0 || height == 0) {
      break;
    }

    size_t row_size = width * pixel_size;
    size_t mipmap_size = row_size * height;

    if (SeekBlob(image, mipmap_size, SEEK_CUR) != mipmap_size) {
      (void) ThrowMagickException(exception, GetMagickModule(), CoderError, "UnableToSkipMipmapData", "");
      return MagickFalse;
    }
  }

  return MagickTrue;
}
